// naive param extraction from a matched pattern
func naive2(pattern, path string) (Params, bool) {
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	var out Params
	for i, seg := range ps {
		if i >= len(xs) {
			return nil, false
		}
		x := xs[i]
		// segment may be: static, :name, *name, static:name, :name.static
		if strings.HasPrefix(seg, "*") {
			if i != len(ps)-1 {
				return nil, false
			}
			out = append(out, Param{seg[1:], "/" + strings.Join(xs[i:], "/")})
			return out, true
		}
		idx := strings.Index(seg, ":")
		if idx < 0 {
			if seg != x {
				return nil, false
			}
			continue
		}
		pre := seg[:idx]
		rest := seg[idx+1:]
		if !strings.HasPrefix(x, pre) {
			return nil, false
		}
		x = x[len(pre):]
		out = append(out, Param{rest, x})
	}
	if len(ps) != len(xs) {
		return nil, false
	}
	return out, true
}

